from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]
PKG = ROOT / 'src' / 'gpt_windows_connector'


def read(path):
    return (ROOT / path).read_text(encoding='utf-8')


def write(path, text):
    (ROOT / path).write_text(text, encoding='utf-8')


def replace_once(text, old, new, label):
    if old not in text:
        raise SystemExit(f'missing marker for {label}')
    return text.replace(old, new, 1)

# 1) Billing: exact annual prices and no invalid Entitlements.stripe_price_id access.
p = 'src/gpt_windows_connector/billing.py'
s = read(p)
if 'ANNUAL_TOTALS' not in s:
    s = replace_once(s, "from .referrals import ReferralService\n", "from .referrals import ReferralService\n\nANNUAL_TOTALS = {'pro': 99.99, 'pro_plus': 199.99, 'expansion': 149.99}\n", 'billing annual constants')
start = s.index('    def summary(self,user_id: str) -> dict[str,Any]:')
end = s.index('    def _require_checkout_configured', start)
summary = '''    def summary(self,user_id: str) -> dict[str,Any]:\n        ent=snapshot(self.db_path,user_id); out=ent.as_dict(); out['billing_configured']=self.checkout_configured; out['webhook_configured']=self.webhook_configured\n        with self._connect() as db:\n            row=db.execute('SELECT billing_customer_id,stripe_subscription_id,stripe_price_id,scheduled_plan FROM subscriptions WHERE user_id=?',(user_id,)).fetchone()\n        out['has_customer']=bool(row and row['billing_customer_id']); out['has_subscription']=bool(row and row['stripe_subscription_id']); out['scheduled_plan']=row['scheduled_plan'] if row else None\n        stripe_price_id=str((row['stripe_price_id'] if row else '') or '')\n        annual_ids={self.price_pro_annual,self.price_pro_plus_annual}\n        interval='year' if stripe_price_id and stripe_price_id in annual_ids else 'month'\n        out['billing_interval']=interval\n        out['annual_billing_configured']=self.annual_checkout_configured\n        monthly=float(PLANS[ent.plan]['price'])+ent.expansion_quantity*float(EXPANSION['price'])\n        out['monthly_price']=round(monthly,2)\n        if interval=='year':\n            base_annual=float(ANNUAL_TOTALS.get(ent.plan,0.0))\n            annual_total=base_annual+ent.expansion_quantity*float(ANNUAL_TOTALS['expansion'])\n            out['billing_total']=round(annual_total,2)\n            out['monthly_equivalent']=round(annual_total/12,2)\n        else:\n            out['billing_total']=round(monthly,2)\n            out['monthly_equivalent']=round(monthly,2)\n        return out\n\n'''
s = s[:start] + summary + s[end:]
write(p, s)

